/**
 * Source of truth mapping each retail product to an animal and butcher cut.
 * Contains authentic anatomical SVG silhouettes and exact retail cut definitions.
 */

import { WOODCUT_MASTER_PATHS } from './woodcutSilhouettes';

export interface CutRecipe {
    title: string;
    prepTime: string;
    cookTime: string;
    method: string;
    internalTemp?: string;
    woodOrPan?: string;
    rubOrSeasoning?: string;
    summary: string;
    steps: string[];
    chefTip: string;
}

export interface CutDefinition {
    id: string;
    name: string;
    animalId: AnimalId;
    order: number;
    svgPath: string;
    labelX: number;
    labelY: number;
    products: string[];
    preparedProducts?: string[];
    isAdventurousCut?: boolean;
    recipe?: CutRecipe;
    callout?: {
        x: number;
        y: number;
        targetX: number;
        targetY: number;
        label: string;
        rectX?: number;
        rectY?: number;
        w?: number;
        h?: number;
    };
}

export type AnimalId = 'beef' | 'pork' | 'chicken' | 'lamb' | 'veal' | 'turkey' | 'duck';

export interface AnimalDefinition {
    id: AnimalId;
    name: string;
    wholeTitle: string;
    stampText: string;
    viewBox: string;
    iconSvg: string;
    vintageChartImage?: string;
    cleanChartImage?: string;
    posterSvg?: string;
    woodcutPath?: string;
    steakHotspots?: {
        id: string;
        label: string;
        featured: string;
        x: number;
        y: number;
        w: number;
        h: number;
    }[];
    cuts: CutDefinition[];
}

